template <typename Ring>
typename Earcut<N>::Node* Earcut<N>::linkedList(const Ring& points, const bool clockwise) {
    using Point = typename Ring::value_type;
    double sum = 0;
    const std::size_t len = points.size();
    std::size_t i = 0, j = (len > 0) ? len - 1 : 0;
    for (; i < len; j = i++) {
        const auto& p1 = points[i];
        const auto& p2 = points[j];
        sum += (p2.first - p1.first) * (p1.second + p2.second);
    }

    Node* last = nullptr;

    if (clockwise == (sum > 0)) {
        for (i = 0; i < len; i++) last = insertNode(verticesIndex + i, points[i].first, points[i].second, last);
    } else {
        for (i = len; i-- > 0;) last = insertNode(verticesIndex + i, points[i].first, points[i].second, last);
    }

    if (last && equals(last, last->next)) {
        removeNode(last);
        last = last->next;
    }

    verticesIndex += len;

    return last;
}
